begin;
select no_plan();
set local role authenticated;
select set_config('request.jwt.claim.sub','10000000-0000-0000-0000-000000000001',true);
select lives_ok($$select public.save_offer_draft('20000000-0000-0000-0000-000000000001','40000000-0000-0000-0000-000000000001',0,jsonb_build_object('title','Workflow offer','price_minor',12345,'quantity',1,'unit','kg','expires_at',now()+interval '2 days'),'50000000-0000-0000-0000-000000000001')$$,'owner creates validated draft');
select lives_ok($$select public.save_offer_draft('20000000-0000-0000-0000-000000000001','40000000-0000-0000-0000-000000000001',0,jsonb_build_object('title','Workflow offer','price_minor',12345,'quantity',1,'unit','kg','expires_at',now()+interval '2 days'),'50000000-0000-0000-0000-000000000001')$$,'retry uses same draft');
select is((select count(*)::int from public.offers where id='40000000-0000-0000-0000-000000000001'),1,'retry does not duplicate');
select is((select version from public.offers where id='40000000-0000-0000-0000-000000000001'),1,'retry does not change version');
select is((select count(*)::int from public.public_offers where id='40000000-0000-0000-0000-000000000001'),0,'draft not public');
select lives_ok($$select public.publish_offer('40000000-0000-0000-0000-000000000001',1,'50000000-0000-0000-0000-000000000002')$$,'owner approves draft publication');
select lives_ok($$select public.publish_offer('40000000-0000-0000-0000-000000000001',1,'50000000-0000-0000-0000-000000000002')$$,'publication retry is safe');
select is((select price_minor from public.public_offers where id='40000000-0000-0000-0000-000000000001'),12345,'approved price is public');
select is((select approved_by::text from public.offers where id='40000000-0000-0000-0000-000000000001'),'10000000-0000-0000-0000-000000000001','approval belongs to current identity');
select throws_ok($$select public.save_offer_draft('20000000-0000-0000-0000-000000000001','40000000-0000-0000-0000-000000000001',1,'{"title":"Stale overwrite"}',gen_random_uuid())$$,'40001',null,'stale edit rejected');
select lives_ok($$select public.save_offer_draft('20000000-0000-0000-0000-000000000001','40000000-0000-0000-0000-000000000001',2,jsonb_build_object('title','Edited workflow offer','price_minor',15000,'expires_at',now()+interval '3 days'),gen_random_uuid())$$,'published changes return to draft');
select is((select count(*)::int from public.public_offers where id='40000000-0000-0000-0000-000000000001'),0,'unapproved edit disappears publicly');
select lives_ok($$select public.publish_offer('40000000-0000-0000-0000-000000000001',3,gen_random_uuid())$$,'edited offer requires approval again');
select lives_ok($$select public.withdraw_offer('40000000-0000-0000-0000-000000000001',4,'50000000-0000-0000-0000-000000000003')$$,'owner withdraws offer');
select lives_ok($$select public.withdraw_offer('40000000-0000-0000-0000-000000000001',4,'50000000-0000-0000-0000-000000000003')$$,'withdrawal retry safe');
select is((select count(*)::int from public.public_offers where id='40000000-0000-0000-0000-000000000001'),0,'withdrawn offer not public');
select is((select count(*)::int from public.audit_events where entity_id='40000000-0000-0000-0000-000000000001'),5,'all lifecycle transitions audited, retries do not duplicate');
select throws_ok($$select public.save_offer_draft('20000000-0000-0000-0000-000000000002',gen_random_uuid(),0,'{"title":"Attack"}',gen_random_uuid())$$,'42501',null,'cross-shop save denied');
select throws_ok($$select public.save_offer_draft('20000000-0000-0000-0000-000000000001',gen_random_uuid(),0,'{"title":"Bad precision","quantity":1.0001,"unit":"kg"}',gen_random_uuid())$$,'P0001',null,'quantity precision rejected');
select throws_ok($$select public.save_offer_draft('20000000-0000-0000-0000-000000000001',gen_random_uuid(),0,'{"title":"Bad pair","quantity":1}',gen_random_uuid())$$,'P0001',null,'ambiguous quantity rejected');
select lives_ok($$select public.save_offer_draft('20000000-0000-0000-0000-000000000001','40000000-0000-0000-0000-000000000002',0,'{"title":"Incomplete draft"}',gen_random_uuid())$$,'incomplete draft can be retained');
select throws_ok($$select public.publish_offer('40000000-0000-0000-0000-000000000002',1,gen_random_uuid())$$,'P0001',null,'incomplete prices and dates cannot publish');
select set_config('request.jwt.claim.sub','10000000-0000-0000-0000-000000000002',true);
select throws_ok($$select public.publish_offer('40000000-0000-0000-0000-000000000002',1,gen_random_uuid())$$,'42501',null,'other owner cannot approve');
select set_config('request.jwt.claim.sub','10000000-0000-0000-0000-000000000003',true);
select throws_ok($$select public.save_offer_draft('20000000-0000-0000-0000-000000000001',gen_random_uuid(),0,'{"title":"Viewer attack"}',gen_random_uuid())$$,'42501',null,'viewer cannot save');
select throws_ok($$select public.publish_offer('40000000-0000-0000-0000-000000000002',1,gen_random_uuid())$$,'42501',null,'viewer cannot publish');
select * from finish();
rollback;
